// Unificar y priorizar citas que necesitan recordatorio de 2h o 24h
const data = $input.first().json.data || { for24h: [], for2h: [] };
const items = [];

(data.for2h || []).forEach(apt => {
  items.push({
    appointment_id: apt.id,
    client_name: apt.client_name,
    client_phone: apt.client_phone,
    datetime: apt.datetime,
    tipo_aviso: '2_HORAS',
    mensaje: `⏰ ¡Hola ${apt.client_name}! Te recordamos que tu cita en la barbería es en menos de 2 horas (${new Date(apt.datetime).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}). ¿Nos confirmas que vienes en camino?`
  });
});

(data.for24h || []).forEach(apt => {
  // Evitar duplicados si ya está en la lista de 2h
  if (!items.find(i => i.appointment_id === apt.id)) {
    items.push({
      appointment_id: apt.id,
      client_name: apt.client_name,
      client_phone: apt.client_phone,
      datetime: apt.datetime,
      tipo_aviso: '24_HORAS',
      mensaje: `💈 ¡Hola ${apt.client_name}! Tienes cita programada para mañana a las ${new Date(apt.datetime).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}. Por favor confirma tu asistencia para mantener tu espacio reservado.`
    });
  }
});

return items.map(i => ({ json: i }));
